def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves starting at any empty cell."""
    cells = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] == ".":
                cells[(r, c)] = len(cells)

    n = len(cells)
    if K >= n:
        return 0

    neighbors = [[] for _ in range(n)]
    for (r, c), i in cells.items():
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = cells.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    def extend(pos: int, visited: int, moves_left: int) -> int:
        if moves_left == 0:
            return 1
        total = 0
        for nxt in neighbors[pos]:
            bit = 1 << nxt
            if not visited & bit:
                total += extend(nxt, visited | bit, moves_left - 1)
        return total

    return sum(extend(i, 1 << i, K) for i in range(n))

