from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = [int(ch) for ch in str(n)]
        total = 0
        max_sum = 9 * len(digits)

        for target_sum in range(1, max_sum + 1):
            @lru_cache(maxsize=None)
            def suffix_ways(pos: int, remaining_sum: int, product_mod: int, started: bool) -> int:
                if remaining_sum < 0 or remaining_sum > 9 * pos:
                    return 0
                if pos == 0:
                    return int(remaining_sum == 0 and started and product_mod == 0)

                ways = 0
                for digit in range(10):
                    next_sum = remaining_sum - digit
                    if next_sum < 0:
                        break
                    if not started and digit == 0:
                        next_mod = product_mod
                        next_started = False
                    else:
                        next_mod = (product_mod * digit) % target_sum
                        next_started = True
                    ways += suffix_ways(pos - 1, next_sum, next_mod, next_started)
                return ways

            remaining_sum = target_sum
            product_mod = 1 % target_sum
            started = False

            for pos, limit_digit in enumerate(digits):
                remaining_positions = len(digits) - pos - 1
                for digit in range(limit_digit):
                    next_sum = remaining_sum - digit
                    if next_sum < 0:
                        break
                    if not started and digit == 0:
                        next_mod = product_mod
                        next_started = False
                    else:
                        next_mod = (product_mod * digit) % target_sum
                        next_started = True
                    total += suffix_ways(
                        remaining_positions, next_sum, next_mod, next_started
                    )

                remaining_sum -= limit_digit
                if remaining_sum < 0:
                    started = started or limit_digit != 0
                    break
                if not started and limit_digit == 0:
                    pass
                else:
                    product_mod = (product_mod * limit_digit) % target_sum
                    started = True
            else:
                if remaining_sum == 0 and started and product_mod == 0:
                    total += 1

        return total

    return count_up_to(r) - count_up_to(l - 1)

