def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts and divisible by k."""
    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = list(map(int, str(limit)))
        total = 0
        # Count each possible number length separately so leading zeroes do not
        # contribute to the even-digit count.
        for length in range(1, len(digits) + 1):
            if length == len(digits):
                bound = digits
            else:
                bound = [9] * length

            # State values count prefixes by (even-minus-odd balance,
            # remainder modulo k, tight-to-bound).
            states = {}
            first_max = bound[0]
            for digit in range(1, first_max + 1):
                tight = digit == first_max
                key = (1 if digit % 2 == 0 else -1, digit % k, tight)
                states[key] = states.get(key, 0) + 1

            for pos in range(1, length):
                next_states = {}
                max_digit = bound[pos]
                for (balance, remainder, tight), ways in states.items():
                    ceiling = max_digit if tight else 9
                    for digit in range(ceiling + 1):
                        next_tight = tight and digit == ceiling
                        next_balance = balance + (1 if digit % 2 == 0 else -1)
                        next_remainder = (remainder * 10 + digit) % k
                        key = (next_balance, next_remainder, next_tight)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states

            total += sum(ways for (balance, remainder, _), ways in states.items()
                         if balance == 0 and remainder == 0)
        return total

    return count_up_to(high) - count_up_to(low - 1)

