def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N strings over 1..K whose only missing length-M
    subsequence is X, modulo 998244353."""
    mod = 998244353

    def onto(length: int, alphabet_size: int) -> int:
        if alphabet_size == 0:
            return int(length == 0)
        if length < alphabet_size:
            return 0
        choose = 1
        total = 0
        for j in range(alphabet_size + 1):
            total += (-1 if j & 1 else 1) * choose * pow(alphabet_size - j, length, mod)
            if j < alphabet_size:
                choose = choose * (alphabet_size - j) % mod
                choose = choose * pow(j + 1, mod - 2, mod) % mod
        return total % mod

    def pair_counts(max_len: int, alphabet_size: int) -> list[int]:
        q = alphabet_size - 2
        side = [0] * (max_len + 1)
        for length in range(2, max_len + 1):
            n = length - 1
            choose = 1
            all_other = 0
            for j in range(q + 1):
                all_other += (-1 if j & 1 else 1) * choose * pow(q + 1 - j, n, mod)
                if j < q:
                    choose = choose * (q - j) % mod
                    choose = choose * pow(j + 1, mod - 2, mod) % mod
            side[length] = (all_other - onto(n, q)) % mod

        conv = [0] * (max_len + 1)
        for left in range(max_len + 1):
            for right in range(max_len + 1 - left):
                conv[left + right] = (conv[left + right] + side[left] * side[right]) % mod
        result = [0] * (max_len + 1)
        for length in range(max_len + 1):
            result[length] = conv[length]
            if length:
                result[length] = (result[length] + q * result[length - 1]) % mod
        return result

    if M == 2:
        x, y = X
        if x == y:
            other = K - 1
            return sum(
                onto(left, other) * onto(N - left - 1, other)
                for left in range(1, N - 1)
            ) % mod
        return pair_counts(N, K)[N]

    if M == 3 and len(set(X)) == 3:
        a, b, z = X
        pairs = pair_counts(N, K)
        # Prefix before the last z contains all pairs except (a,b). After
        # the last z, the first b completes (a,b); its preceding letters
        # cannot be b, and its suffix must contain every non-z symbol.
        after = [0] * (N + 1)
        for length in range(1, N + 1):
            after[length] = sum(
                pow(K - 2, end - 1, mod) * onto(length - end, K - 1)
                for end in range(1, length + 1)
            ) % mod
        return sum(pairs[prefix] * after[N - prefix - 1]
                   for prefix in range(N)) % mod

    is_constant = all(v == X[0] for v in X)
    minimum = M * K - (1 if is_constant else 0)
    if N < minimum:
        return 0
    if is_constant and N == minimum:
        factorial = 1
        for value in range(1, K):
            factorial = factorial * value % mod
        return pow(factorial, M, mod)
    return 0

