from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover an H×W grid."""
    if h <= 0 or w <= 0 or n < 0 or n > len(tiles):
        return False

    sizes = tiles[:n]
    areas = [a * b for a, b in sizes]
    target = h * w
    full_row = (1 << w) - 1
    all_tiles = (1 << n) - 1

    subset_sums = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        i = bit.bit_length() - 1
        subset_sums[mask] = subset_sums[mask ^ bit] + areas[i]

    @lru_cache(None)
    def search(rows: Tuple[int, ...], used: int) -> bool:
        remaining = target - sum(row.bit_count() for row in rows)
        if remaining == 0:
            return True

        # Find the first uncovered cell in row-major order.
        for r, row in enumerate(rows):
            if row != full_row:
                c = 0
                while row & (1 << c):
                    c += 1
                break

        # Remaining tile areas must be able to sum to the uncovered area.
        if not any(
            subset_sums[subset] == remaining and (subset & used) == 0
            for subset in range(1 << n)
        ):
            return False

        for i, (a, b) in enumerate(sizes):
            if (used >> i) & 1 or areas[i] > remaining:
                continue
            for height, width in {(a, b), (b, a)}:
                # Try every placement that contains the first empty cell. This
                # also keeps the search valid if the empty-cell ordering changes.
                for top in range(max(0, r - height + 1), r + 1):
                    if top + height > h:
                        continue
                    for left in range(max(0, c - width + 1), c + 1):
                        if left + width > w:
                            continue
                        if not (top <= r < top + height and left <= c < left + width):
                            continue
                        bits = ((1 << width) - 1) << left
                        if any(rows[y] & bits for y in range(top, top + height)):
                            continue
                        updated = list(rows)
                        for y in range(top, top + height):
                            updated[y] |= bits
                        if search(tuple(updated), used | (1 << i)):
                            return True
        return False

    return search((0,) * h, 0)

