def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    A cell is fixed when its value is forced by the row and column sums.
    """
    if k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # A nontrivial set of exchangeable cells can be arranged as a rectangle:
    # its two side lengths count the rows and columns participating in the
    # exchanges. Every other cell is forced.
    free = n * n - k
    for rows in range(2, n + 1):
        if free % rows == 0 and 2 <= free // rows <= n:
            return True
    return False

