from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_h(i, j):
        return (i - j) % 2 == 0

    sk = S_y % K if is_h(si, sj) else S_x % K
    tk = T_y % K if is_h(ti, tj) else T_x % K
    start, goal = (si, sj, sk), (ti, tj, tk)
    if start == goal:
        return 0

    dx, dy = ti - si, tj - sj
    span = abs(dx) + abs(dy)

    # Alternating monotone crossings have no intermediate lane changes for
    # equal nonzero displacements. Check that the final required strip is the
    # target lane before using this lower-bound path.
    if abs(dx) == abs(dy) and dx != 0:
        if is_h(si, sj):
            required = 0 if dy > 0 else K - 1
            if is_h(ti, tj) and tk == required:
                return span
        else:
            required = 0 if dx > 0 else K - 1
            if not is_h(ti, tj) and tk == required:
                return span

    lanes = sorted({0, K - 1, sk, tk})
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, (i, j, k) = heappop(heap)
        state = (i, j, k)
        if d != dist[state]:
            continue
        if state == goal:
            return d

        for q in lanes:
            nd = d + abs(k - q)
            nxt = (i, j, q)
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))

        h = is_h(i, j)
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            src_fixed = dst_fixed = None
            if h and di == 0:
                src_fixed = K - 1 if dj > 0 else 0
            elif h and dj == 0:
                dst_fixed = 0 if di > 0 else K - 1
            elif not h and di == 0:
                dst_fixed = 0 if dj > 0 else K - 1
            else:
                src_fixed = K - 1 if di > 0 else 0

            if src_fixed is not None and k != src_fixed:
                continue
            for q in lanes:
                if dst_fixed is not None and q != dst_fixed:
                    continue
                nxt = (ni, nj, q)
                nd = d + 1
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))
    return span

