def count_in_degree_sequences(n: int, s: str) -> int:
    """ Given a positive integer n and a string s of length n consisting of '0' and '1',
    construct a graph G with (n+1) vertices numbered 0 to n, with the following edges:
    - For each i from 0 to n-1, there's an edge between vertices i and (i+1) mod n
    - For each i from 0 to n-1, there's an edge between vertices i and n if s[i] == '1'

    Create a directed graph G' by assigning a direction to each edge of G.
    For each vertex i, let d_i be its in-degree in G'.

    Return the number of distinct sequences (d_0, d_1, ..., d_n) that can be obtained,
    modulo 998244353.

    Args:
        n: A positive integer (3 <= n <= 10^6)
        s: A string of length n consisting only of '0' and '1'

    Returns:
        The number of distinct in-degree sequences modulo 998244353

    >>> count_in_degree_sequences(3, '010')
    14
    >>> count_in_degree_sequences(20, '00001100111010100101')
    261339902
    """
    mod = 998244353

    # A relation is a 2x2 Boolean matrix, encoded row-major in four bits.
    # At position i, the prior and next cycle-edge directions are the row
    # and column states. If they are x and y, the cycle contribution is
    # 1 + x - y. A spoke, when present, can add either zero or one.
    labels = {}
    for spoke in (0, 1):
        by_degree = {}
        for degree in range(4):
            matrix = 0
            for before in (0, 1):
                for after in (0, 1):
                    base = 1 + before - after
                    if degree - base in ((0, 1) if spoke else (0,)):
                        matrix |= 1 << (2 * before + after)
            if matrix:
                by_degree[degree] = matrix
        labels[spoke] = tuple(by_degree.values())

    compose = [[0] * 16 for _ in range(16)]
    for first in range(16):
        for second in range(16):
            result = 0
            for a in (0, 1):
                for b in (0, 1):
                    if first & (1 << (2 * a + b)):
                        for c in (0, 1):
                            if second & (1 << (2 * b + c)):
                                result |= 1 << (2 * a + c)
            compose[first][second] = result

    # Count words by their resulting relation. The sequence is realizable by
    # a cyclic orientation exactly when this relation has a diagonal entry.
    counts = [0] * 16
    counts[9] = 1  # identity relation: the cycle starts in either state
    for bit in s:
        transitions = labels[bit == "1"]
        following = [0] * 16
        for relation, ways in enumerate(counts):
            if ways:
                for transition in transitions:
                    state = compose[relation][transition]
                    following[state] = (following[state] + ways) % mod
        counts = following

    return sum(counts[mask] for mask in range(16) if mask & 9) % mod

