from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count sequences whose product n<=N has sum of divisors divisible by 3."""
    if N <= 1:
        return 0

    # For n=prod(p**e), the number of ordered M-tuples with product n is
    # prod C(M+e-1,e).
    max_e = 33
    ways = [1] + [0] * max_e
    for e in range(1, max_e + 1):
        ways[e] = ways[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    limit = 100000
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * ((limit - start) // p + 1)
    primes = [i for i in range(2, limit + 1) if sieve[i]]
    pi_small = [0] * (limit + 1)
    count = 0
    for i in range(limit + 1):
        if sieve[i]:
            count += 1
        pi_small[i] = count

    @lru_cache(maxsize=None)
    def phi(x, s):
        if s == 0:
            return x
        if s == 1:
            return x - x // 2
        if primes[s - 1] >= x:
            return 1
        return phi(x, s - 1) - phi(x // primes[s - 1], s - 1)

    @lru_cache(maxsize=None)
    def prime_pi(x):
        if x <= limit:
            return pi_small[x]
        a = prime_pi(isqrt(isqrt(x)))
        b = prime_pi(isqrt(x))
        c = prime_pi(int(round(x ** (1 / 3))))
        while (c + 1) ** 3 <= x:
            c += 1
        while c ** 3 > x:
            c -= 1
        result = phi(x, a) + (b + a - 2) * (b - a + 1) // 2
        for i in range(a, b):
            w = x // primes[i]
            result -= prime_pi(w)
            if i < c:
                for j in range(i, prime_pi(isqrt(w))):
                    result -= prime_pi(w // primes[j]) - j
        return result

    def unrestricted(weights):
        @lru_cache(maxsize=None)
        def rec(x, start):
            if x <= 1:
                return 1
            root = isqrt(x)
            # Exponent-one prime factors above sqrt(x) have no cofactor left.
            first_tail = max(pi_small[root], start)
            lower = primes[first_tail - 1] if first_tail > pi_small[root] else root
            result = 1 + weights[1] * (prime_pi(x) - prime_pi(lower))
            for idx in range(start, pi_small[root]):
                p = primes[idx]
                power = p
                e = 1
                while power <= x:
                    coeff = weights[e]
                    if coeff:
                        result += coeff * rec(x // power, idx + 1)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            return result % MOD
        return rec

    all_sum = unrestricted(ways)(N, 0)

    # A local divisor sum is zero modulo 3 for p=1 mod 3 and e=2 mod 3,
    # or p=2 mod 3 and odd e. Such an integer is good iff at least one
    # prime-power factor has this property.
    @lru_cache(maxsize=None)
    def no_zero_local_factor(x, start):
        if x <= 1:
            return 1
        root = isqrt(x)
        first_tail = max(pi_small[root], start)
        lower = primes[first_tail - 1] if first_tail > pi_small[root] else root
        result = 1 + ways[1] * (prime_pi(x) - prime_pi(lower))
        for idx in range(start, pi_small[root]):
            p = primes[idx]
            if p == 3:
                weights = ways
            elif p % 3 == 1:
                weights = [ways[e] if e % 3 != 2 else 0 for e in range(max_e + 1)]
            else:
                weights = [ways[e] if e % 2 == 0 else 0 for e in range(max_e + 1)]
            power = p
            e = 1
            while power <= x:
                coeff = weights[e]
                if coeff:
                    result += coeff * no_zero_local_factor(x // power, idx + 1)
                e += 1
                if power > x // p:
                    break
                power *= p
        return result % MOD

    return (all_sum - no_zero_local_factor(N, 0)) % MOD
